.mode list
WITH den AS (SELECT substr(d.date_iso,1,3)||'0s' dec, COUNT(*) n FROM document_dates d JOIN document_cache c ON c.volume_id=d.volume_id AND c.document_id=d.document_id WHERE d.date_iso IS NOT NULL AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2') GROUP BY 1),
num AS (SELECT substr(d.date_iso,1,3)||'0s' dec, COUNT(*) n FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE frus_documents MATCH 'corrupt*' AND d.date_iso IS NOT NULL AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2') GROUP BY 1),
uni AS (SELECT substr(d.date_iso,1,3)||'0s' dec, COUNT(*) n FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE frus_documents MATCH 'corrupt* OR briberi OR bribe*' AND d.date_iso IS NOT NULL AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2') GROUP BY 1),
bri AS (SELECT substr(d.date_iso,1,3)||'0s' dec, COUNT(*) n FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE frus_documents MATCH 'briberi OR bribe*' AND d.date_iso IS NOT NULL AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2') GROUP BY 1)
SELECT den.dec, den.n AS dated, coalesce(num.n,0) AS corrupt, round(1000.0*coalesce(num.n,0)/den.n,2) AS corrupt_per_1000, coalesce(bri.n,0) AS bribe, round(1000.0*coalesce(bri.n,0)/den.n,2) AS bribe_per_1000, coalesce(uni.n,0) AS union_n, round(1000.0*coalesce(uni.n,0)/den.n,2) AS union_per_1000 FROM den LEFT JOIN num ON num.dec=den.dec LEFT JOIN bri ON bri.dec=den.dec LEFT JOIN uni ON uni.dec=den.dec WHERE den.dec >= '1920s' AND den.dec <= '1990s' ORDER BY 1;
SELECT '--1940s corrupt* by volume top', c.volume_id, COUNT(*) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE frus_documents MATCH 'corrupt*' AND d.date_iso LIKE '194%' AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2') GROUP BY 2 ORDER BY 3 DESC LIMIT 3;
SELECT '--1920s+1930s combined corrupt* per 1000', round(1000.0*(SELECT COUNT(*) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid JOIN document_dates d ON d.volume_id=c.volume_id AND d.document_id=c.document_id WHERE frus_documents MATCH 'corrupt*' AND (d.date_iso LIKE '192%' OR d.date_iso LIKE '193%') AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2'))/(SELECT COUNT(*) FROM document_dates d JOIN document_cache c ON c.volume_id=d.volume_id AND c.document_id=d.document_id WHERE (d.date_iso LIKE '192%' OR d.date_iso LIKE '193%') AND c.is_front_matter=0 AND c.is_editorial_note=0 AND c.volume_id NOT IN ('frus1951-54IranEd2','frus1969-76ve15p2Ed2')),2);
SELECT '--volume count ever matching dept of state (control)', COUNT(DISTINCT c.volume_id) FROM frus_documents f JOIN document_cache c ON c.rowid=f.rowid WHERE frus_documents MATCH '"department of state"' AND c.is_front_matter=0 AND c.is_editorial_note=0;
SELECT '--MAX date', MAX(date_iso) FROM document_dates;
